Definition art_fsinv_frame_law : Prop :=
  forall rn gfs FF LK M M', FSINV rn gfs FF LK M -> mem_grows M M' -> (forall x : word, art_fs_zone rn (U x) -> M' x = M x) -> FSINV rn gfs FF LK M'.
