#[using="g M I"] Lemma fsinv_slot : forall f, In f (FF ++ LK) ->
  0 <= ff_class f <= 5 /\ exists i, 0 <= i < fs_nfr (ff_class f) /\ ff_addr f = fs_frame fs (ff_class f) i.
