(* [comment removed for export] *)
Lemma nodup_app_disj : forall (A B : Type) (g : A -> B) (l1 l2 : list A) x y, List.NoDup (map g (l1 ++ l2)) -> In x l1 -> In y l2 -> g x <> g y.
Proof.
