#[local] Ltac zstat := intros z Hz; cbn in Hz; first [ left; unfold art_zone_statics; lia | do 7 right; left; lia ].
#[local] Ltac timg := apply fl_cell_img; [first [lia|cbn; lia] | first [lia|cbn; lia] | zstat | assumption].

(* [comment removed for export] *)
#[using="FSG MAPS0 RESV0 G LB M REP AG LIVEOK KN"] Lemma fl_statics : art_rt_statics rn M'.
Proof.
pose proof REP as (ROK & ST & _). rok_open ROK. pose proof GEO as GEO'. geo_open GEO'. destruct ST as (PC & L & T & RO & RZ & DR & TG & CS). unfold art_rt_statics. split. { unfold art_prim_consts in *. decompose [and] PC. repeat split; timg. } split. { unfold art_layout in *. decompose [and] L. repeat split; timg. } split. { destruct T as (C1 & C2 & C3 & C4 & C5 & RR). pose proof RR as (_ & _ & Hkey' & _). unfold art_tsd. split; [timg|]. split; [timg|]. split. { apply fl_cell_img; [lia|cbn; lia| |exact C3]. intros z Hz. cbn in Hz. do 8 right. left. lia. } split. { apply fl_cell_img; [lia|cbn; lia| |exact C4]. intros z Hz. cbn in Hz. do 9 right. left. lia. } split; [|exact RR]. apply fl_cell; [lia|cbn; lia| |exact C5]. intros z Hz. cbn in Hz. split; [right; right; left; lia|apply fl_nb_ctx; lia]. } split. { unfold art_alloc_rodata in *. decompose [and] RO. repeat split; timg. } split. { unfold art_rz_rodata in *. decompose [and] RZ. repeat split; timg. } split. { unfold DRoD in *. decompose [and] DR. repeat split; timg. } split. { destruct TG as (GN & T1 & T2). split; [|split]. - intros a Ha. rewrite (AG (Z_to_bv 64 a)); [exact (GN a Ha)|rewrite art_u_lit by lia; do 7 right; left; lia|rewrite art_u_lit by lia; apply fl_nb_img; lia]. - apply fl_cell_img; [lia|cbn; lia| |exact T1]. intros z Hz. cbn in Hz. do 10 right. left. lia. - apply fl_cell_img; [lia|cbn; lia| |exact T2]. intros z Hz. cbn in Hz. do 11 right. lia. } decompose [and] CS. repeat split; timg. Qed.

